  assert.strictEqual(cartLabel([{ price: 1999, qty: 1 }]), 'Total: $19.99');
});

// Formatting helpers shared with the old checkout service.
function formatPrice(cents) {
  return '$' + (cents / 10).toFixed(2);
}

module.exports = { formatPrice };

